using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace PlainApi.Evals.Tests;

[TestClass]
public class ApiEvaluationTests
{
    private static WebApplicationFactory<Program> _factory = null!;
    private static HttpClient _client = null!;

    [ClassInitialize]
    public static void ClassInit(TestContext context)
    {
        _factory = new WebApplicationFactory<Program>();
        _client = _factory.CreateClient();
    }

    [ClassCleanup]
    public static void ClassCleanup()
    {
        _client.Dispose();
        _factory.Dispose();
    }

    [TestMethod]
    public async Task RootEndpoint_ReturnsExpectedResponse()
    {
        var response = await _client.GetAsync("/");
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync();

        Assert.AreEqual("Hello, World!", content);
    }

    [TestMethod]
    public async Task HealthEndpoint_ReturnsHealthy()
    {
        var response = await _client.GetAsync("/health");
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync();

        Assert.IsTrue(content.Contains("healthy"));
    }

    [TestMethod]
    public async Task RootEndpoint_ResponseQuality_Evaluation()
    {
        var response = await _client.GetAsync("/");
        var content = await response.Content.ReadAsStringAsync();

        // Use NLP-based evaluators (no LLM API key required)
        var evaluators = new IEvaluator[]
        {
            new StringSimilarityEvaluator()
        };

        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            await evaluator.EvaluateAsync(
                [new ChatMessage(ChatRole.Assistant, content)],
                result,
                new ChatConfiguration(chatClient: null!),
                additionalContext:
                [
                    new EvaluationContext("reference", "Hello, World!")
                ]);
        }

        // Verify that evaluation produced metrics
        Assert.IsTrue(result.Metrics.Count > 0, "Evaluation should produce metrics");

        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(metric.Value.Diagnostics.Any(d => d.Severity == EvaluationDiagnosticSeverity.Error),
                $"Metric '{metric.Key}' has error diagnostics");
        }
    }
}

